use vstd::prelude::*;

verus! {
    // A simple closed interval [lower, upper], with the invariant lower < upper.
    struct Interval {
        lower: i32,
        upper: i32,
    }

    // A Chebyshev polynomial descriptor with:
    //  - coef: the polynomial coefficients in increasing degree order
    //  - domain: the x‐domain interval
    //  - window: the window (typically y‐range) interval
    struct ChebyshevPoly {
        coef: Vec<i32>,
        domain: Interval,
        window: Interval,
    }

    // The chebyshev function
    fn chebyshev(coef: Vec<i8>) -> (result: ChebyshevPoly)
        requires
            // input must be nonempty
            coef.len() > 0,
        ensures
            // the output coefficient vector has the same length
            result.coef.len() == coef.len(),
        ensures
            // each coefficient has been reified to i32, in the same order
            forall |i: usize| i < coef.len() ==> result.coef[i] == (coef[i] as i32),
        ensures
            // domain and window are both exactly [-1,1]
            result.domain.lower == -1 && result.domain.upper == 1,
        ensures
            result.window.lower == -1 && result.window.upper == 1,
        ensures
            // and both intervals are valid (lower < upper)
            result.domain.lower < result.domain.upper,
        ensures
            result.window.lower < result.window.upper,
    {
        // 1) Build the Vec<i32> by casting each i8 -> i32
        let mut coef32: Vec<i32> = Vec::new();
        let mut idx: usize = 0;
        while idx < coef.len()
            invariant
                idx <= coef.len(),
                coef32.len() == idx,
                // for all positions we have already done the correct cast
                forall |j: usize| j < idx ==> coef32[j] == (coef[j] as i32),
            decreases
                coef.len() - idx
        {
            // push the next coefficient
            coef32.push(coef[idx] as i32);
            idx += 1;
        }

        // 2) Set up the default intervals [-1,1]
        let domain = Interval { lower: -1, upper: 1 };
        let window = Interval { lower: -1, upper: 1 };

        // 3) Assemble the result
        let result = ChebyshevPoly {
            coef: coef32,
            domain,
            window,
        };

        // 4) Now discharge the remaining post‐conditions
        assert(result.coef.len() == coef.len());
        assert(forall |i: usize| i < coef.len() ==> result.coef[i] == (coef[i] as i32));
        assert(result.domain.lower == -1 && result.domain.upper == 1);
        assert(result.window.lower == -1 && result.window.upper == 1);
        assert(result.domain.lower < result.domain.upper);
        assert(result.window.lower < result.window.upper);

        result
    }
}

